package main

import (
	"errors"
	"path/filepath"
	"strings"
	"testing"
)

// m7GeneratedPlans is the reason a candidate gives the regenerable half of
// the SQL adapter, the first contract of its entry named.
const m7GeneratedPlans = m7PlansPath + m7GolawFrom + m7PortsPath + " (port Ledger)" + m7GeneratedSuffix

// m7DenialKinds stands in for golaw new: the generated files the rows edit
// written once, by the first command.
func m7DenialKinds(t *testing.T, c command) {
	t.Helper()
	if c.args[2] != m7Commands()[0].name {
		return
	}
	header := "// Code generated by golaw 0.7.0 kind=port@1; DO NOT EDIT.\n\n"
	m2Write(t, filepath.Join(c.dir, filepath.FromSlash(m7FakePath)), header+m7FakeClause)
	m2Write(t, filepath.Join(c.dir, filepath.FromSlash(m7PlansPath)), header+"package postgres\n")
	m2Write(t, filepath.Join(c.dir, filepath.FromSlash(m7OwnedPlans)), "package postgres\n")
}

// m7DenialReplies stand in for a candidate whose agents deny every write
// with reason, or allow every write when reason is empty; Cursor allows
// before its write and feeds back after it.
func m7DenialReplies(t *testing.T, reason, fed string) []m5Reply {
	t.Helper()
	deny := map[string]any{"systemMessage": "A operação foi bloqueada.", "hookSpecificOutput": map[string]string{
		"hookEventName": eventPre, "permissionDecision": wantDeny, "permissionDecisionReason": reason,
	}}
	cursor := 0
	return []m5Reply{
		m6InitReply(),
		{prefix: []string{"new"}, answer: m5After(m7DenialKinds, result{})},
		{prefix: []string{commandHook, agentClaude}, answer: func(t *testing.T, _ command) result {
			t.Helper()
			if reason == "" {
				return result{}
			}
			return result{stdout: m6JSON(t, deny)}
		}},
		{prefix: []string{commandHook, agentCodex}, answer: func(t *testing.T, _ command) result {
			t.Helper()
			if reason == "" {
				return result{}
			}
			return result{stdout: m6JSON(t, deny), stderr: reason + "\n"}
		}},
		{prefix: []string{commandHook, agentCursor}, answer: func(t *testing.T, _ command) result {
			t.Helper()
			cursor++
			if cursor%2 == 1 {
				return result{stdout: `{"permission":"allow"}` + "\n"}
			}
			return result{stdout: m6JSON(t, map[string]string{"additional_context": fed})}
		}},
	}
}

// m7RunDenial runs one m7-denial row by name over the replies.
func m7RunDenial(t *testing.T, name string, replies []m5Reply) error {
	t.Helper()
	s := newM7Suite(m2TestSuite(t))
	s.execute = m5Script(t, s.suite, replies...).Execute
	for _, c := range m7DenialCases() {
		if c.name == name {
			return c.run(s.m7Scope(m7DenialCategory, c.name), t.Context())
		}
	}
	t.Fatalf("no denial row %s", name)
	return nil
}

func TestM7DenialRowsPassOverACandidateThatDeniesWithTheAddendumLines(t *testing.T) {
	t.Parallel()
	feedback := m7FakePath + ":1 " + m7FakeReason
	for name, reason := range map[string]string{
		"claude-write": m7FakeReason, "claude-edit": m7FakeReason, "claude-redirect": m7FakeReason,
		"codex-update": m7FakeReason, "codex-delete": m7FakeReason, "codex-redirect": m7FakeReason,
		"cursor-feedback": m7FakeReason, "third-party": m7QueriesReason, "header-stripped": m7GeneratedPlans,
		"manifest-write": m7ManifestReason, "handwritten-bare": m7BareReason, "near-misses": "",
	} {
		if err := m7RunDenial(t, name, m7DenialReplies(t, reason, feedback)); err != nil {
			t.Fatalf("%s: %v", name, err)
		}
	}
}

// TestM7DenialRowsFailOnAFalseOrAMissedDenial: another sentence, a feedback
// without the fix, a near miss denied, a write allowed and an adoption the
// candidate refuses each fail the row.
func TestM7DenialRowsFailOnAFalseOrAMissedDenial(t *testing.T) {
	t.Parallel()
	refused := []m5Reply{{prefix: []string{commandInit}, answer: m5Answer(result{code: 2, stderr: "golaw: refused\n"})}}
	for _, tc := range []struct {
		name, row, want string
		replies         []m5Reply
	}{
		{"red another sentence", "claude-write", "want", m7DenialReplies(t, m7QueriesReason, "")},
		{"red codex another sentence", "codex-redirect", "want", m7DenialReplies(t, m7BareReason, "")},
		{"red the stripped header unnamed", "header-stripped", "does not name", m7DenialReplies(t, m7FakeReason, "")},
		{"red the feedback without the fix", "cursor-feedback", "lacks", m7DenialReplies(t, m7FakeReason, m7FakePath)},
		{"red a near miss denied", "near-misses", "does not satisfy", m7DenialReplies(t, m7FakeReason, "")},
		{"red a write allowed", "claude-edit", "does not satisfy", m7DenialReplies(t, "", "")},
		{"red codex allowed", "codex-delete", "", m7DenialReplies(t, "", "")},
		{"red the adoption refused", "third-party", "adopt the fixture repository", refused},
		{"red the shell adoption refused", "claude-redirect", "adopt the fixture repository", refused},
	} {
		err := m7RunDenial(t, tc.row, tc.replies)
		if !errors.Is(err, ErrAcceptance) || !strings.Contains(err.Error(), tc.want) {
			t.Fatalf("%s: %v, want an error naming %q", tc.name, err, tc.want)
		}
	}
}
